import java.io.*;
import java.nio.charset.StandardCharsets;
import net.runelite.cache.NpcManager;
import net.runelite.cache.fs.Store;
import net.runelite.cache.definitions.NpcDefinition;

/** Offline development tool; run against a COPY of the cache, never the live cache. */
public class DumpNpcs {
    public static void main(String[] args) throws Exception {
        try (Store store = new Store(new File(args[0]))) {
            store.load();
            NpcManager manager = new NpcManager(store);
            manager.load();
            try (PrintWriter out = new PrintWriter(args[1], StandardCharsets.UTF_8.name())) {
                out.println("id\tname\tidle\twalk\tfollower\tmodels\ttextures");
                for (NpcDefinition npc : manager.getNpcs()) {
                    if (npc.models != null && npc.models.length > 0)
                        out.printf("%d\t%s\t%d\t%d\t%s\t%s\t%s%n", npc.id, npc.name,
                            npc.standingAnimation, npc.walkingAnimation, npc.isFollower,
                            java.util.Arrays.toString(npc.models),
                            java.util.Arrays.toString(npc.retextureToFind) + ":" + java.util.Arrays.toString(npc.retextureToReplace));
                }
            }
        }
    }
}

package com.cornydonkeh.varrockstraycats;

import net.runelite.api.ModelData;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ModelCopyTest
{
    @Test
    public void untexturedCatModelDoesNotCloneMissingTextureArray()
    {
        ModelData data = mock(ModelData.class);
        when(data.cloneVertices()).thenReturn(data);
        when(data.cloneColors()).thenReturn(data);
        when(data.getFaceTextures()).thenReturn(null);
        when(data.cloneTextures()).thenThrow(new NullPointerException("No face textures"));

        assertSame(data, VarrockStrayCatsPlugin.copyMutableModelData(data));
        verify(data).cloneVertices();
        verify(data).cloneColors();
        verify(data, never()).cloneTextures();
    }

    @Test
    public void texturedPetModelCopiesTexturesBeforeRetexturing()
    {
        ModelData data = mock(ModelData.class);
        ModelData textureCopy = mock(ModelData.class);
        when(data.cloneVertices()).thenReturn(data);
        when(data.cloneColors()).thenReturn(data);
        when(data.getFaceTextures()).thenReturn(new short[] {1});
        when(data.cloneTextures()).thenReturn(textureCopy);

        assertSame(textureCopy, VarrockStrayCatsPlugin.copyMutableModelData(data));
        verify(data).cloneTextures();
    }
}

package com.cornydonkeh.varrockstraycats;

import net.runelite.api.NPC;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import org.mockito.InOrder;
import static org.mockito.Mockito.*;

public class ReplacementPlacementTest
{
    @Test
    public void replacementIsPositionedOnTheStrayBeforeBeingRegistered()
    {
        NPC npc = mock(NPC.class);
        RuneLiteObject replacement = mock(RuneLiteObject.class);
        LocalPoint location = new LocalPoint(6400, 6400);
        when(npc.getLocalLocation()).thenReturn(location);
        when(npc.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
        when(npc.getCurrentOrientation()).thenReturn(512);

        VarrockStrayCatsPlugin.positionReplacement(npc, replacement);

        InOrder order = inOrder(replacement);
        order.verify(replacement).setLocation(location, 0);
        order.verify(replacement).setOrientation(512);
        order.verify(replacement).isActive();
        order.verify(replacement).setActive(true);
    }

    @Test
    public void alreadyRegisteredReplacementMovesWithoutRegisteringAgain()
    {
        NPC npc = mock(NPC.class);
        RuneLiteObject replacement = mock(RuneLiteObject.class);
        LocalPoint location = new LocalPoint(6528, 6400);
        when(npc.getLocalLocation()).thenReturn(location);
        when(npc.getWorldLocation()).thenReturn(new WorldPoint(3201, 3200, 0));
        when(replacement.isActive()).thenReturn(true);

        VarrockStrayCatsPlugin.positionReplacement(npc, replacement);

        verify(replacement).setLocation(location, 0);
        verify(replacement, never()).setActive(true);
    }
}

package com.cornydonkeh.varrockstraycats;

import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.mockito.Mockito.*;

public class ConfigMigrationTest
{
    @Test
    public void migratesFavoritesWithoutOverwritingNewSettings()
    {
        ConfigManager manager = mock(ConfigManager.class);
        when(manager.getConfiguration("healthydogs", "appearanceGrowncatHell")).thenReturn("true");
        when(manager.getConfiguration("varrockstraycats", "randomBreeds")).thenReturn("false");

        VarrockStrayCatsPlugin.migrateConfig(manager);

        verify(manager).setConfiguration("varrockstraycats", "appearanceGrowncatHell", "true");
        verify(manager, never()).getConfiguration("healthydogs", "randomBreeds");
        verify(manager, never()).setConfiguration(eq("varrockstraycats"), eq("randomBreeds"), any());
    }
}

